css:
& .am-panel-id { display:none; }
& .am-toolbar { display:none; }
& .am-comment-btn { display:none; }
& .am-reply { display:none; }
& .am-colophon { display:none; }
& .am-doc { max-width:1390px; margin:0 0 0 268px; padding:40px 44px 64px; }
& .am-head { border:0; padding:0 0 28px; margin:0; }
& .am-head h1 { font:700 clamp(26px,2.7vw,38px)/1.45 var(--font-sans); letter-spacing:-.02em; max-width:940px; }
& .am-sub { font:15px/1.8 var(--font-sans); color:var(--ink-2); margin-top:10px; }
& .am-intro { font-size:14px; margin-top:16px; }
& .am-doc-layout { grid-template-columns:minmax(0,1fr) 190px; gap:30px; align-items:start; }
& .am-doc-body { grid-column:1; grid-row:1; min-width:0; }
& .am-toc { grid-column:2; grid-row:1; top:30px; max-height:calc(100vh - 60px); overflow:auto; border-left:1px solid var(--line-2); padding-left:16px; }
& .am-toc a { font:13px/1.75 var(--font-sans); padding:7px 0; border:0; }
& .course-toc-title { font-size:12px; font-weight:700; color:var(--ink-3); margin-bottom:10px; }
& .am-panel { border:1px solid var(--line-2); border-radius:12px; margin-bottom:24px; box-shadow:0 3px 18px #1b354005; overflow:hidden; }
& .am-panel-head { border-bottom:1px solid var(--line-2); background:var(--paper); padding:22px 28px 16px; min-height:0; }
& .am-panel-head h2 { font:700 21px/1.5 var(--font-sans); padding:0; text-transform:none; letter-spacing:0; }
& .am-panel-body { padding:22px 28px 26px; }
& .am-md { font:16px/1.95 var(--font-sans); }
& .am-md p { margin:0 0 16px; }
& .am-md h3 { font-size:18px; line-height:1.6; margin:28px 0 12px; }
& .am-md a { text-underline-offset:4px; }
& .am-md th { background:var(--fill); font-size:13px; letter-spacing:0; text-transform:none; }
& .am-md td { font-size:14px; line-height:1.8; padding:12px; }
& .am-code { border-radius:9px; margin:20px 0; }
& .am-code pre { font-size:13px; line-height:1.8; }
& .am-figure { margin:24px 0; }
& .am-figure figcaption { color:var(--ink-2); font-size:13px; line-height:1.8; }
& .course-sidebar { box-sizing:border-box; position:fixed; inset:0 auto 0 0; width:268px; z-index:30; display:flex; flex-direction:column; padding:28px 18px 16px; border-right:1px solid var(--line); background:var(--paper); }
& .course-eyebrow { font:700 10px/1.6 var(--font-sans); letter-spacing:.13em; color:var(--accent); padding:0 12px 7px; }
& .course-brand { color:var(--ink); text-decoration:none; font:700 21px/1.5 var(--font-sans); padding:0 12px; }
& .course-side-description { font:12px/1.6 var(--font-sans); color:var(--ink-3); padding:0 12px; margin:6px 0 18px; }
& .course-search { box-sizing:border-box; width:100%; padding:11px; border:1px solid var(--line); border-radius:8px; color:var(--ink); background:var(--bg); font:12px/1.5 var(--font-sans); margin-bottom:14px; }
& .course-lessons { overflow:auto; min-height:0; flex:1; overscroll-behavior:contain; }
& .course-nav-group { margin:8px 0 17px; }
& .course-nav-group h2 { font:700 11px/1.7 var(--font-sans); color:var(--ink-3); padding:0 12px; margin:0 0 5px; }
& .course-lesson-link { display:flex; align-items:baseline; gap:8px; padding:8px 11px; border-radius:7px; text-decoration:none; color:var(--ink-2); font:13px/1.65 var(--font-sans); }
& .course-lesson-link:hover { background:var(--fill); color:var(--ink); }
& .course-lesson-link.is-active { background:var(--accent-bg); color:var(--accent); font-weight:700; }
& .course-lesson-number { width:28px; flex-shrink:0; font:11px/1.6 var(--font-mono); }
& .course-complete-dot { margin-left:auto; font-size:12px; color:var(--ok); }
& .course-utilities { display:flex; gap:5px 14px; flex-wrap:wrap; padding:14px 10px 0; border-top:1px solid var(--line-2); }
& .course-utilities a { font:11px/1.8 var(--font-sans); color:var(--ink-2); text-decoration:none; }
& .course-progress-count { margin:10px 10px 0; font:10px/1.7 var(--font-sans); color:var(--ink-3); }
& .course-breadcrumb { display:flex; flex-wrap:wrap; gap:8px; font:12px/1.6 var(--font-sans); color:var(--ink-3); margin-bottom:18px; }
& .course-breadcrumb a { color:var(--ink-2); text-decoration:none; }
& .course-page-meta { display:flex; flex-direction:column; gap:7px; font:13px/1.75 var(--font-sans); padding:16px 20px; border-left:3px solid var(--accent); background:var(--accent-bg); border-radius:0 8px 8px 0; margin-top:20px; max-width:860px; }
& .course-page-meta a { color:var(--accent); }
& .course-completion { background:var(--accent-bg); border:1px solid var(--line-2); padding:26px 28px; border-radius:12px; margin-top:28px; }
& .course-completion h2 { font:700 20px/1.5 var(--font-sans); margin:0 0 12px; }
& .course-completion p { font:14px/1.8 var(--font-sans); }
& .course-primary-button { padding:12px 20px; border:0; border-radius:8px; background:var(--accent); color:var(--paper); font:700 14px/1.5 var(--font-sans); cursor:pointer; }
& .course-storage-note { color:var(--ink-2); font-size:12px !important; margin-bottom:0; }
& .course-resume-link { display:inline-block; margin-top:16px; color:var(--accent); font-size:14px; }
& .course-empty { padding:12px; color:var(--ink-2); font-size:12px; line-height:1.8; }
& .course-mobile-bar { display:none; }
& [hidden] { display:none !important; }
@media (max-width:1180px) { & .am-doc { padding:30px 26px 50px; } & .am-doc-layout { grid-template-columns:minmax(0,1fr); } & .am-toc { grid-column:1; grid-row:1; position:static; max-height:none; display:flex; flex-wrap:wrap; gap:4px 15px; padding:0 0 20px; border:0; } & .course-toc-title { flex-basis:100%; } & .am-doc-body { grid-column:1; grid-row:2; } }
@media (max-width:880px) { & .course-sidebar { display:none; top:58px; width:280px; box-shadow:15px 0 40px #10203025; } & .course-menu-open .course-sidebar { display:flex; } & .course-mobile-bar { display:flex; position:sticky; top:0; height:58px; align-items:center; justify-content:space-between; padding:0 18px; background:var(--paper); border-bottom:1px solid var(--line); z-index:40; } & .course-mobile-bar a { text-decoration:none; color:var(--ink); font-weight:700; font-size:15px; } & .course-menu-button { padding:7px 12px; border:1px solid var(--line); border-radius:6px; background:var(--paper); color:var(--ink); font:12px/1.5 var(--font-sans); } & .am-doc { margin:0; padding:26px 16px 45px; } & .am-panel-head { padding:20px 18px 14px; } & .am-panel-body { padding:18px; } & .am-md { font-size:15px; line-height:1.9; } & .am-head h1 { font-size:28px; } & .am-md th { min-width:6em; } & .am-md td { min-width:6em; } & .course-completion { padding:22px 18px; } }
@media print { & .course-sidebar { display:none; } & .course-mobile-bar { display:none; } & .am-doc { margin:0; } & .course-completion { display:none; } }
